DROP TABLE IF EXISTS `news_news`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news_news` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `slug` varchar(220) NOT NULL,
  `summary` varchar(500) NOT NULL,
  `content` longtext NOT NULL,
  `category` varchar(20) NOT NULL,
  `thumbnail_url` varchar(500) NOT NULL,
  `is_published` tinyint(1) NOT NULL,
  `views_count` int unsigned NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `author_id` bigint NOT NULL,
  `department_id` bigint DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tin nổi bật pin lên đầu danh sách',
  `thumbnail_image` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `news_news_created_33ef44_idx` (`created_at` DESC),
  KEY `news_news_categor_5b8b50_idx` (`category`,`created_at` DESC),
  KEY `news_news_slug_915ecd_idx` (`slug`),
  KEY `news_news_author_id_9f88be71_fk_accounts_customuser_id` (`author_id`),
  KEY `news_news_department_id_3dfbd046_fk_questions_department_id` (`department_id`),
  CONSTRAINT `news_news_author_id_9f88be71_fk_accounts_customuser_id` FOREIGN KEY (`author_id`) REFERENCES `accounts_customuser` (`id`),
  CONSTRAINT `news_news_department_id_3dfbd046_fk_questions_department_id` FOREIGN KEY (`department_id`) REFERENCES `questions_department` (`id`),
  CONSTRAINT `news_news_chk_1` CHECK ((`views_count` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

